files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #0069d9;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #FFFFFF;
  --vt-accent-on-deep: #4da3ff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background-color: var(--vt-surface);
  color: var(--vt-ink);
  line-height: 1.5;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface-2);
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  padding: 1rem 0;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 15px;
}

.logo {
  text-decoration: none;
  color: var(--vt-accent);
}

.navLinks {
  display: flex;
  gap: 1.5rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  padding: 0.5rem 0;
  transition: color 0.3s;
}

.navLinks a:hover,
.root a:focus-visible {
  color: var(--vt-ink);
}

.hero {
  position: relative;
  height: 580px;
  overflow: hidden;
  margin-top: 94px;
}

.heroImage {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
}

.heroText {
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  width: 50%;
  background: var(--vt-surface);
  padding: 2rem 2.5rem;
  box-sizing: border-box;
}

.kicker {
  color: var(--vt-accent);
  text-transform: uppercase;
  letter-spacing: 2px;
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.heroTitle {
  font-size: 3rem;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 1rem;
}

.heroWord {
  display: block;
  color: var(--vt-accent);
}

.heroIntro {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.cta {
  display: inline-block;
  padding: 0.75rem 2rem;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  text-decoration: none;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border: 1px solid var(--vt-accent);
  transition: all 0.3s;
}

.cta:hover {
  background: transparent;
  color: var(--vt-accent);
}

.contactPhone {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--vt-ink);
  font-weight: 600;
  margin: 0;
}

.phoneIcon {
  font-style: normal;
  display: inline-block;
  width: 1em;
  text-align: center;
}

.phoneIcon::before {
  content: '\260E';
}

.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.about {
  background: var(--vt-surface);
}

.aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.aboutText {
  flex: 1;
  min-width: 300px;
  padding: 0 15px;
}

.aboutTitle {
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 1.1rem;
  line-height: 1.7;
}

.gallery {
  background: var(--vt-surface);
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
  margin: 0;
}

.galleryItem {
  width: 50%;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  height: auto;
  display: block;
}

.timelineSection {
  background: var(--vt-surface-2);
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.timelineTitle {
  text-align: center;
  font-size: 2.25rem;
  font-weight: 700;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
}

.timeline::before {
  content: '';
  position: absolute;
  top: 20px;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 1px;
  background: var(--vt-line);
}

.timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  margin-bottom: 2rem;
}

.timelineNode.odd {
  flex-direction: row;
}

.timelineNode.even {
  flex-direction: row-reverse;
}

.timelineContent {
  width: 45%;
  background: var(--vt-surface);
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.1);
  border-radius: 4px;
  padding: 0;
}

.timelineNodeTitle {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  font-size: 1.25rem;
  font-weight: 600;
  border-radius: 4px 4px 0 0;
  position: relative;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
  line-height: 1.6;
}

.timelineIcon {
  width: 40px;
  height: 40px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  z-index: 10;
  margin: 0 1rem;
  position: relative;
}

.timelineDate {
  width: 30%;
  padding: 1.5rem 1rem;
  color: var(--vt-ink-soft);
  font-weight: 600;
}

.odd .timelineDate {
  text-align: left;
}

.even .timelineDate {
  text-align: right;
}

.timelineNode.odd .timelineNodeTitle::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even .timelineNodeTitle::after {
  content: '';
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.siteFooter {
  background: var(--vt-surface-2);
  padding-top: 5rem;
  padding-bottom: 5rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.footerCol {
  flex: 1;
  min-width: 200px;
}

.footerTitle {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.footerCol p {
  color: var(--vt-ink-soft);
  margin: 0.5rem 0;
}

.socialLinks {
  display: flex;
  gap: 1rem;
}

.copyrightText {
  color: var(--vt-ink-soft);
  font-size: 0.9rem;
  margin-top: 2rem;
}

@media (max-width: 991px) {
  .hero {
    height: auto;
    margin-top: 74px;
  }
  .heroText {
    position: relative;
    bottom: 0;
    right: 0;
    width: auto;
    margin: 0 auto;
    padding: 2rem;
    box-shadow: none;
  }
  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }
}

@media (max-width: 767px) {
  .navIn {
    flex-direction: column;
  }
  .navLinks {
    gap: 0.5rem;
    flex-wrap: wrap;
    justify-content: center;
  }
  .timeline::before {
    left: 20px;
  }
  .timelineNode,
  .timelineNode.odd,
  .timelineNode.even {
    flex-direction: column;
    align-items: flex-start;
    padding-left: 60px;
  }
  .timelineContent,
  .timelineDate {
    width: 100%;
  }
  .timelineIcon {
    position: absolute;
    left: 0;
    top: 0;
  }
  .timelineNodeTitle::after {
    display: none;
  }
  .footerRow {
    flex-direction: column;
  }
}

@media (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }
  .heroTitle {
    font-size: 2rem;
  }
}
